sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float threshold;
layout(color) uniform half4 color;
uniform float blend;
uniform float alpha;
uniform float style;
uniform float4 screen;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float4 shaded(float2 at, float2 cell, float3 k) {
    float4 c = float4(image.eval(at));
    return float4(c.rgb * (1.0 - clamp(alpha, 0.0, 1.0) * float(blurred.eval(cell).r) * k), c.a);
}
half4 standard(float2 coord) {
    float2 shift = fract(-screen.xy * 0.5);
    float2 q = coord * 0.5 + shift - 0.5;
    float2 i0 = floor(q);
    float2 f = q - i0;
    float2 cell = i0 + 0.5;
    float2 at = 2.0 * (cell - shift);
    float3 k = 1.0 - clamp(blend, 0.0, 1.0) * float3(color.rgb);
    float4 top = mix(shaded(at, cell, k), shaded(at + float2(2.0, 0.0), cell + float2(1.0, 0.0), k), f.x);
    float4 low = mix(shaded(at + float2(0.0, 2.0), cell + float2(0.0, 1.0), k), shaded(at + float2(2.0, 2.0), cell + float2(1.0, 1.0), k), f.x);
    return half4(mix(top, low, f.y));
}
half4 main(float2 coord) {
    if (style > 0.5) return standard(coord);
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    half4 b = blurred.eval(coord);
    float lb = b.a > 0.0 ? luma(float3(b.rgb) / float(b.a)) : 1.0;
    float dark = clamp((threshold - lb) / max(threshold, 0.001), 0.0, 1.0) * clamp(float(b.a), 0.0, 1.0);
    float3 base = float3(src.rgb) / float(src.a);
    float3 shade = mix(base * float3(color.rgb), float3(color.rgb), 1.0 - clamp(blend, 0.0, 1.0));
    float3 rgb = mix(base, shade, dark * clamp(alpha, 0.0, 1.0));
    return half4(half3(rgb) * src.a, src.a);
}
